"""Count Occurrences in a Sorted Array — upper bound minus lower bound.

Time: O(log n)   Space: O(1)
"""
from typing import List


class Solution:
    def countOccurrences(self, nums: List[int], x: int) -> int:
        def bound(value: int) -> int:
            lo, hi = 0, len(nums)
            while lo < hi:
                mid = (lo + hi) // 2
                if nums[mid] < value:
                    lo = mid + 1
                else:
                    hi = mid
            return lo

        return bound(x + 1) - bound(x)
